const body = $input.first().json.body || $input.first().json;
const attachments = body.attachments || [];

const refMatch = body.subject?.match(/Ref\s+A?(\d+)/i);
const refNumber = refMatch ? refMatch[1] : '';

const output = {
  to: body.to,
  subject: body.subject,
  htmlBody: body.htmlBody,
  replyTo: body.replyTo || '',
  threadId: body.threadId || '',
  refNumber: refNumber,
  searchQuery: refNumber ? `subject:${refNumber}` : '',
  hasAttachments: attachments.length > 0,
};

const binaryData = {};
for (let i = 0; i < attachments.length; i++) {
  const att = attachments[i];
  binaryData[`attachment_${i}`] = {
    data: att.data,
    mimeType: att.type || 'application/octet-stream',
    fileName: att.name || `attachment_${i}`,
  };
}

return [{ json: output, binary: Object.keys(binaryData).length > 0 ? binaryData : undefined }];

const original = $('Procesar Datos').first().json;
const binaryData = $('Procesar Datos').first().binary;

const searchResult = $input.first().json;
let finalSubject = original.subject;
let threadId = original.threadId || '';
let cc = '';

if (searchResult && searchResult.threadId) {
  threadId = searchResult.threadId;

  // Extract subject from Gmail full response
  let foundSubject = '';
  const headers = searchResult.payload?.headers || [];
  for (const h of headers) {
    if (h.name === 'Subject') { foundSubject = h.value; break; }
  }
  // Fallback: try direct field
  if (!foundSubject) foundSubject = searchResult.Subject || searchResult.subject || '';

  const origSubject = foundSubject.replace(/^(Re:\s*)+/i, '').trim();
  if (origSubject) {
    finalSubject = 'Re: ' + origSubject;
  }

  // Extract CC for reply-all
  let ccRaw = '';
  let toRaw = '';
  for (const h of headers) {
    if (h.name === 'Cc') ccRaw = h.value;
    if (h.name === 'To') toRaw = h.value;
  }
  if (!ccRaw) ccRaw = searchResult.Cc || searchResult.cc || '';
  if (!toRaw) toRaw = searchResult.To || searchResult.to || '';

  const allRecipients = [toRaw, ccRaw]
    .join(',')
    .split(',')
    .map(e => e.trim())
    .filter(e => e && !e.toLowerCase().includes('bridvanovich@twf'));

  cc = [...new Set(allRecipients)].join(', ');
}

return [{
  json: {
    to: original.to,
    subject: finalSubject,
    htmlBody: original.htmlBody,
    threadId: threadId,
    cc: cc,
    hasAttachments: original.hasAttachments,
  },
  binary: binaryData || undefined,
}];
